import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { fetchArticle } from "../api";

export default function NewsDetail() {
  const { id } = useParams();
  const [article, setArticle] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchArticle(id)
      .then((a) => setArticle(a))
      .catch(console.error)
      .finally(() => setLoading(false));
  }, [id]);

  if (loading) return <div className="news-loading">Đang tải...</div>;
  if (!article) return <div>Không tìm thấy bài viết.</div>;

  return (
    <div className="news-detail container">
      <h1>{article.title}</h1>
      <p className="news-meta">{article.source} • {article.publishedAt ? new Date(article.publishedAt).toLocaleString() : ""}</p>
      {article.thumbnail && <img className="detail-thumb" src={article.thumbnail} alt={article.title} />}
      <div className="news-content" dangerouslySetInnerHTML={{ __html: article.content || `<p>${article.excerpt}</p><p><a href="${article.link}" target="_blank" rel="noreferrer">Xem bài gốc</a></p>` }} />
      <p><a href={article.link} target="_blank" rel="noreferrer">Xem nguồn gốc bài gốc</a></p>
    </div>
  );
}
